import { FileText, Search } from 'lucide-react';
import { resolveAssetUrl } from '../../config/loadConfig';
import type { ResourceConfig } from '../../config/schema';
import { prefetchResourceViewer } from '../../shared/prefetch';
import { ResourceViewer } from '../../features/archive/ResourceViewer';
import { cardVisual, resourceBadge, splitTitle } from '../../features/archive/resourceGroups';
import { kindFilters, useArchiveList, views } from '../../features/archive/useArchiveList';

/**
 * 新 UI 档案页（Concept A · 深海蓝沉浸展厅）——步骤 4 换结构的那一页。
 *
 * 与旧页面的差别只在**排布**，不在数据：
 *  - 旧页：小缩略图列表卡（图像在下、名称在下），眉标用 `feature-hero`；
 *  - 新页：图像主导的大卡（标题压在图上、年份用档案米），分区标题栏用青色竖条，
 *    专辑视图每一辑一条分区栏；
 *  - 筛选、检索、排序、滚动恢复、详情翻页全部来自 `useArchiveList()`——与旧页面**同一份实现**，
 *    所以两套结构不可能在"搜什么、怎么排"上分叉。
 *
 * 详情仍复用 `features/archive/ResourceViewer`（PDF/图片查看器、资料抽屉都在里面）。
 */
function ArchiveCard({ resource, onOpen }: { resource: ResourceConfig; onOpen(): void }) {
  const { thumb, badge } = cardVisual(resource);
  const kindLabel = resourceBadge(resource).kind;
  const title = splitTitle(resource.title);
  return (
    <button
      type="button"
      className="next-archive-card"
      data-kind={resource.kind}
      onPointerEnter={() => prefetchResourceViewer(resource.kind)}
      onFocus={() => prefetchResourceViewer(resource.kind)}
      onClick={onOpen}
      aria-label={`打开${resource.title}`}
    >
      <span className="next-archive-media">
        {thumb
          ? <img src={resolveAssetUrl(thumb)} alt="" loading="lazy" decoding="async" />
          : <span className="next-archive-paper"><FileText aria-hidden="true" /></span>}
        <i className="next-archive-kind">{kindLabel}</i>
        {badge && <em className="next-archive-badge">{badge}</em>}
      </span>
      <span className="next-archive-cap">
        <strong>{title.main}</strong>
        {title.suffix && <em className="next-archive-year">{title.suffix}</em>}
      </span>
    </button>
  );
}

export function ArchivePage() {
  const { config, query, setQuery, kind, setKind, view, setView, resources, grouped, viewer, openResource } = useArchiveList();

  if (viewer) return <ResourceViewer {...viewer} />;

  // 眉标第二行用数据自己的年代跨度（不写死年份；没有年代资料时退回拉丁小字）。
  const years = config.resources
    .map(resource => resource.period?.year)
    .filter((year): year is number => typeof year === 'number');
  const span = years.length ? `${Math.min(...years)} — ${Math.max(...years)}` : 'KNOWLEDGE BASE';

  return (
    <section className="next-archive">
      <header className="next-archive-head">
        <div className="next-eyebrow">
          <i aria-hidden="true" />
          <div>
            <b>历史档案</b>
            {span}
          </div>
        </div>
        <div className="next-archive-titlerow">
          <h1 className="next-page-title">数字档案</h1>
          {/* 视图 = "怎么排布这批资料"；筛选 = "看哪些资料"。 */}
          <div className="next-segmented" role="group" aria-label="档案视图">
            {views.map(item => (
              <button
                type="button"
                key={item.value}
                aria-pressed={view === item.value}
                className={view === item.value ? 'is-active' : undefined}
                onClick={() => setView(item.value)}
              >
                {item.label}
              </button>
            ))}
          </div>
        </div>
        <p className="next-lede">按类型与专辑检索</p>
      </header>

      <label className="next-search">
        <Search aria-hidden="true" />
        <span className="sr-only">搜索数字档案</span>
        <input
          type="search"
          aria-label="搜索数字档案"
          value={query}
          onChange={event => setQuery(event.target.value)}
          placeholder="搜索标题、说明或原始文件名"
        />
      </label>

      <div className="next-chips" aria-label="档案类型">
        {kindFilters.map(filter => (
          <button
            type="button"
            key={filter.value}
            aria-pressed={kind === filter.value}
            className={kind === filter.value ? 'is-active' : undefined}
            onClick={() => setKind(filter.value)}
          >
            {filter.label}
          </button>
        ))}
      </div>

      <div className="next-archive-results">
        {view === 'grid' && (
          <div className="next-archive-grid">
            {resources.map(resource => (
              <ArchiveCard key={resource.id} resource={resource} onOpen={() => openResource(resource.id)} />
            ))}
          </div>
        )}
        {view !== 'grid' && grouped.map(group => (
          <section className="next-archive-album" key={group.key} aria-label={group.label}>
            <header className="next-section-bar">
              <i aria-hidden="true" />
              <strong>{group.label}</strong>
              <span>{group.items.length} 项</span>
            </header>
            {group.summary && <p className="next-archive-summary">{group.summary}</p>}
            <div className="next-archive-grid">
              {group.items.map(resource => (
                <ArchiveCard key={resource.id} resource={resource} onOpen={() => openResource(resource.id)} />
              ))}
            </div>
          </section>
        ))}
        {!resources.length && <p className="next-archive-empty">没有匹配的档案</p>}
      </div>
    </section>
  );
}
